//-----------------------------------------------------------------------------
// @file: tb_pixel_line_buff.sv
//
// @brief: SystemVerilog testbench for pixel_line_buff (VHDL DUT).
// Load in test vector generated by line_buff_sim.mlx for simulating inputs   
// and comparing output. 
//-----------------------------------------------------------------------------
`timescale 1ns / 1ps

import pkg_edge_detection::*;

module tb_sobel_filter;
    //-------------------------------------------------------------------------
    // Parameters 
    //-------------------------------------------------------------------------
    localparam CLK_PERIOD = 3.33; // 250 mhz clock period

    // TB driven 
    logic clk = 1'b0;
    logic rstn = 1'b1;
    logic [COMPONENT_WIDTH_C-1:0 ] grey_pixel = 'b0;
    logic pixel_valid = 1'b0;
    logic [15:0] x = 1'b0;
    logic [15:0] y = 1'b0;

    // DUT driven

    // pixel line buff:
    window_flat_t flat_window ;
    logic window_valid ;

    // sobel filter:
    logic [COMPONENT_WIDTH_C-1:0] mag;
    logic mag_valid;

    pixel_line_buff_wrap pixel_line_buff_wrap_instance (
        .clk_i(clk),
        .rstn_i(rstn),
        .greyscale_pixel_i(grey_pixel),
        .pixel_valid_i(pixel_valid),
        .x_i(x),
        .y_i(y),
        .window_o(flat_window),
        .window_valid_o(window_valid)
    );

    sobel_filter_wrap sobel_filter_wrap_instance (
        .clk_i(clk),
        .rstn_i(rstn),
        .window_i(flat_window),
        .window_valid_i(window_valid),
        .mag_valid_o(mag_valid),
        .mag_o(mag)
    );

    //-------------------------------------------------------------------------
    // TB variables
    //-------------------------------------------------------------------------

    // clock generation 
    initial clk = 0;
    always #(CLK_PERIOD/2) clk = ~clk;

    //test vector step up
    int fd; // file descriptor 
    string header; // remove test vector header  

    // test vector inputs
    int pxl_tv; //pixel test vector
    int pv_tv; // pixel valid test vector
    int x_pxl_tv; // x pixel position test vector
    int y_pxl_tv; // y pixel position test vector
    int wv_tv; // window valid test vector
    int gx_tv; // gradient x position test vector
    int gy_tv; // gradient y position test vector

    // test vector outputs
    window_t window_exp; // window expected
    int mag_valid_exp;
    int mag_exp;

    // intermediate signal for unflattening the sliding window
    window_t window;

    //-------------------------------------------------------------------------
    // Test counters
    //-------------------------------------------------------------------------
    int test_count   = 0;
    int pass_count   = 0;
    int fail_count   = 0;
    int skip_count   = 0;

    //-------------------------------------------------------------------------
    // Helper tasks
    //-------------------------------------------------------------------------

    // Equality check for any vector up to 64 bits wide. Narrower arguments
    // are extended on the call (sign-extended if declared signed, else zero),
    // so exp and act must both be signed or both unsigned. 4-state compare:
    // an X or Z in either operand counts as a mismatch.
    task check(input logic [63:0] exp, input logic [63:0] act, input string msg = "");
        test_count++;
        if (exp === act) begin
            pass_count++;
        end else begin
            fail_count++;
            $error("FAIL [%0d]: %s expected %0d (0x%0h), actual %0d (0x%0h) (time=%0t)",
                test_count, msg, exp, exp, act, act, $time);
            $finish;
        end
    endtask

    // Wait N clock cycles
    task wait_clocks(input int n);
        repeat (n) @(posedge clk);
    endtask


    task automatic reset();
        wait_clocks(1);
        rstn = 1'b0;
        wait_clocks(1);
        rstn = 1'b1;
        wait_clocks(1);
    endtask


    // main
    initial begin
        // set up test vector file
        // @todo: explain vivado path finding  
        fd = $fopen("/home/petalinux/Documents/edge-detection-fpga/matlab_prototypes/sobel_test_vector.txt", "r");
        if (fd == 0) $fatal(1, "cannot open test vector");
        void'($fgets(header, fd)); // remove header

        // rest dut
        reset();

        // $feof only reports end of file after a read has already failed.
        // must compare the number of ints scanned to break the loop.
        while ($fscanf(fd, "%d %d %d %d", pxl_tv, pv_tv, x_pxl_tv, y_pxl_tv) == 4) begin
            // pack to window array
            for (int r = 0; r < WINDOW_SIZE_C; r++) begin
                for (int c = 0; c < WINDOW_SIZE_C; c++) begin
                    void'($fscanf(fd, "%d", window_exp[r][c]));
                end
            end
            $fscanf(fd, "%d %d %d %d %d", wv_tv, gx_tv, gy_tv, mag_exp, mag_valid_exp);

            // inputs to pixel line buffer
            grey_pixel = pxl_tv;
            pixel_valid = pv_tv;
            x = x_pxl_tv;
            y = y_pxl_tv;

            wait_clocks(1);

            // unflatten window
            window = unflatten_window(flat_window);

            // check sliding window valid
            check(wv_tv, window_valid, "slide window valid check failed");

            if (wv_tv == 1'b1) begin
                // only check when window expected is valid
                `CHECK_WINDOW_EQ_CNT(window, window_exp, "windows", test_count, pass_count, fail_count)
            end

            // check gradient magnitude 
            check(mag_valid_exp, mag_valid, "gradient magnitude valid");
            check(mag_exp, mag, "gradient magnitude");

        end

        $finish;
    end

endmodule
